#!/usr/bin/env bash
# Regenerate the refinement corpus bytecode from solar at a pinned commit.
#
#   scripts/refinement/gen.sh           rewrite SolidCore/Refinement/{Bytecode,Source}/*.lean
#   scripts/refinement/gen.sh --check   the same, then fail if any generated file changed
#
# Each scripts/refinement/corpus/NAME.sol holds one contract named Main. For
# each, the script writes
#   SolidCore/Refinement/Bytecode/NAME.lean  solar's runtime bytecode and selectors
#   SolidCore/Refinement/Source/NAME.lean    the SolidCore source AST, through
#                                            scripts/solc_ast_to_lean_source.py
#   SolidCore/Refinement/Corpus/NAME*.lean   the refinement proof of each name in
#                                            scripts/refinement/kept, through
#                                            scripts/refinement/gen_proof.py
# and SolidCore/Refinement/Corpus.lean imports every proof. A line
# "// refinement: solar-flags=F1,F2" in a source passes F1 and F2 to solar; the
# bytecode file then records the flags and the runtime's SHA-256.
#
# The names in scripts/refinement/certified (the corpus contracts that certified libraries
# import) must get a proof the kernel checks alone, without native_decide or bv_decide:
# gen_proof.py refuses their fallbacks and scripts/refinement/kernel_only.py checks the
# written modules.
#
# scripts/refinement/solar-rev names the paradigmxyz/solar commit, built here
# with cargo into SOLAR_DIR (default .cache/solar). SOLAR_BIN skips the build and
# uses that binary instead, which must report the pinned commit. The source AST
# comes from solc 0.8.35, downloaded and checked against its SHA-256 unless SOLC
# names a binary.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

check=0
[[ "${1-}" == "--check" ]] && check=1

rev="$(tr -d '[:space:]' < scripts/refinement/solar-rev)"
solar_dir="${SOLAR_DIR:-.cache/solar}"

if [[ -z "${SOLAR_BIN-}" ]]; then
  if [[ ! -d "$solar_dir/.git" ]]; then
    git init -q "$solar_dir"
    git -C "$solar_dir" remote add origin https://github.com/paradigmxyz/solar.git
  fi
  git -C "$solar_dir" fetch -q --depth 1 origin "$rev"
  git -C "$solar_dir" checkout -q --detach "$rev"
  cargo build --release --locked --manifest-path "$solar_dir/Cargo.toml" --bin solar
  SOLAR_BIN="$solar_dir/target/release/solar"
fi

version="$("$SOLAR_BIN" --version | head -n 1)"
if [[ "$version" != *"${rev:0:7}"* ]]; then
  echo "error: $SOLAR_BIN reports '$version', not commit $rev" >&2
  exit 1
fi

solc_version=0.8.35
solc_sha256=fa8ac9a32d301ad023a36ee5a29f8e291fe3200c60244e43c142539e82a617f4
if [[ -z "${SOLC-}" ]]; then
  SOLC=".cache/solc-$solc_version"
  if [[ ! -x "$SOLC" ]]; then
    mkdir -p .cache
    curl -fsSL -o "$SOLC.tmp" \
      "https://github.com/argotorg/solidity/releases/download/v$solc_version/solc-static-linux"
    echo "$solc_sha256  $SOLC.tmp" | sha256sum -c --quiet
    chmod +x "$SOLC.tmp"
    mv "$SOLC.tmp" "$SOLC"
  fi
fi

out=SolidCore/Refinement/Bytecode
src_out=SolidCore/Refinement/Source
proof_out=SolidCore/Refinement/Corpus
rm -rf "$proof_out"
mkdir -p "$out" "$src_out" "$proof_out"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
proved=()
for sol in scripts/refinement/corpus/*.sol; do
  name="$(basename "$sol" .sol)"
  module="$(echo "${name:0:1}" | tr '[:lower:]' '[:upper:]')${name:1}"
  # A line "// refinement: solar-flags=F1,F2" passes F1 and F2 to solar.
  solar_flags=()
  flags_line="$(sed -n 's|^//[[:space:]]*refinement:.*solar-flags=\([^[:space:]]*\).*$|\1|p' "$sol" | head -n 1)"
  if [[ -n "$flags_line" ]]; then
    IFS=, read -r -a solar_flags <<< "$flags_line"
  fi
  json="$("$SOLAR_BIN" ${solar_flags[@]+"${solar_flags[@]}"} --emit bin-runtime,hashes --no-warnings "$sol")"
  python3 - "$json" "$name" "$module" "$rev" "$version" "$sol" "${solar_flags[*]-}" > "$out/$module.lean" <<'EOF'
import hashlib, json, sys
blob, name, module, rev, version, sol, flags = sys.argv[1:]
contracts = json.loads(blob)["contracts"]
lines = [
    "-- Generated by scripts/refinement/gen.sh. Do not edit.",
    f"-- Source: {sol}",
    f"-- solar: {version}",
    f"-- solar commit: {rev}",
]
if flags:
    lines += [f"-- solar flags: {flags}"]
lines += [
    "",
    f"namespace SolidCore.Refinement.Bytecode.{module}",
    "",
    f'def solarRev : String := "{rev}"',
]
for key in sorted(contracts):
    c = contracts[key]
    cname = key.rsplit(":", 1)[1]
    code = c["bin-runtime"]
    lines += [
        "",
        f"/-- Runtime bytecode of `{cname}` as solar emits it, read big-endian. -/",
        f"def {cname}.runtimeNat : Nat :=",
        f"  0x{code}",
        "",
        f"/-- Length of `{cname}`'s runtime bytecode in bytes. -/",
        f"def {cname}.runtimeSize : Nat := {len(code) // 2}",
    ]
    if flags:
        digest = hashlib.sha256(bytes.fromhex(code)).hexdigest()
        lines += [
            "",
            f"/-- SHA-256 of `{cname}`'s runtime bytecode, from solar with `{flags}`. -/",
            f'def {cname}.runtimeSha256 : String := "{digest}"',
        ]
    for sig, sel in sorted((c.get("hashes") or {}).items()):
        ident = sig.split("(")[0]
        lines += [
            "",
            f"/-- Selector of `{sig}`. -/",
            f"def {cname}.{ident}Selector : Nat := 0x{sel}",
        ]
lines += ["", f"end SolidCore.Refinement.Bytecode.{module}", ""]
sys.stdout.write("\n".join(lines))
EOF
  {
    echo "-- Generated by scripts/refinement/gen.sh from $sol with solc $solc_version. Do not edit."
    echo
    echo "import SolidCore.Solidity.Checked"
    echo
    echo "open SolidCore.Solidity"
    echo
    python3 scripts/solc_ast_to_lean_source.py "$sol" --contract Main --solc "$SOLC" \
      --namespace "SolidCore.Refinement.Source.$module" --body-only \
      | sed "s|^def importedSourceName : String := .*$|def importedSourceName : String := \"$sol\"|"
  } > "$src_out/$module.lean"
  echo "$sol -> $out/$module.lean, $src_out/$module.lean"
  # Only the names in scripts/refinement/kept get a committed proof; the rest stop at bytecode
  # and source.
  if ! grep -qx "$name" scripts/refinement/kept; then
    if grep -qx "$name" scripts/refinement/certified; then
      echo "error: $sol is certified but not in scripts/refinement/kept" >&2
      exit 1
    fi
    continue
  fi
  "$SOLAR_BIN" ${solar_flags[@]+"${solar_flags[@]}"} --emit abi,hashes --no-warnings "$sol" > "$tmp/solar.json"
  "$SOLC" --combined-json ast "$sol" > "$tmp/ast.json"
  # A name in scripts/refinement/certified must get a proof the kernel checks alone.
  certified=0
  grep -qx "$name" scripts/refinement/certified && certified=1
  status=0
  REFINEMENT_CERTIFIED=$certified python3 scripts/refinement/gen_proof.py "$name" "$module" \
    "$tmp/solar.json" "$tmp/ast.json" "$sol" || status=$?
  if (( status == 0 )); then
    proved+=("$module")
    if (( certified )); then
      python3 scripts/refinement/kernel_only.py "SolidCore.Refinement.Corpus.$module"
    fi
  elif (( status != 3 )); then
    exit "$status"
  elif (( certified )); then
    echo "error: $sol is certified but gets no proof" >&2
    exit 1
  fi
done

{
  echo "-- Generated by scripts/refinement/gen.sh. Do not edit."
  echo
  for module in "${proved[@]}"; do
    echo "import SolidCore.Refinement.Corpus.$module"
  done
  echo
  echo "/-! The refinement proofs of every contract in scripts/refinement/corpus/. -/"
} > "$proof_out.lean"

if (( check )); then
  if ! git diff --exit-code -- "$out" "$src_out" "$proof_out" "$proof_out.lean"; then
    echo "error: generated bytecode differs from the checked-in files; run scripts/refinement/gen.sh" >&2
    exit 1
  fi
  if [[ -n "$(git ls-files --others --exclude-standard -- "$out" "$src_out" "$proof_out")" ]]; then
    echo "error: untracked generated files in $out, $src_out or $proof_out" >&2
    exit 1
  fi
fi

